mapper.select:
SELECT uploader_id, thumbnail_object_key FROM ( SELECT uploader_id, thumbnail_object_key, ROW_NUMBER() OVER (PARTITION BY uploader_id ORDER BY created_at DESC, id DESC) AS rn FROM image WHERE is_delete = 0 AND audit_status = 1 AND thumbnail_object_key IS NOT NULL AND thumbnail_object_key <> '' AND uploader_id IN
#{uploaderId}
) ranked WHERE rn <= #{limitPerUser} ORDER BY uploader_id, rn
